using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace FTRez.LobbyModel
{
    // Global shader inputs named by SceneRenderAgent, TerminalRoomEnvRenderer,
    // TerminalRoomComp, UGC2GameSystem and UGCObjectConcertWaveShock in the SDK.
    // URP camera textures/light buffers are regenerated by the captured renderer.
    internal sealed class ShaderState
    {
        static readonly string[] floats = { "_G_DirLight_Intensity", "_ChromaIntensity", "_SpreadRadius", "_SpreadFade",
            "enableFogParam", "_FullScreenCapture", "_ObliqueProjection" };
        static readonly string[] vectors = { "_G_DirLight_Dir", "_G_DirLight_Color", "_G_Fog_Color", "_G_FogParams",
            "_ChromaDir", "_SpreadCenter", "_FogCenterPosition", "_FogCenterNormal" };
        static readonly string[] colors = { "_FogColorAncient", "_FogColorModern" };
        static readonly int modelIntensity = Shader.PropertyToID("_G_DirLight_Intensity");
        static readonly int[] modelVectors = { Shader.PropertyToID("_G_DirLight_Dir"), Shader.PropertyToID("_G_DirLight_Color"),
            Shader.PropertyToID("_G_Fog_Color"), Shader.PropertyToID("_G_FogParams") };
        readonly float[] floatValues = new float[floats.Length];
        readonly Vector4[] vectorValues = new Vector4[vectors.Length];
        readonly Color[] colorValues = new Color[colors.Length];
        GlobalKeyword[] keywords;
        readonly HashSet<string> desired = new HashSet<string>();
        public ShaderState()
        { Capture(); }
        public void Capture()
        {
            keywords = Shader.enabledGlobalKeywords;
            desired.Clear(); foreach (var keyword in keywords) desired.Add(keyword.name);
            for (int i = 0; i < floats.Length; ++i) floatValues[i] = Shader.GetGlobalFloat(floats[i]);
            for (int i = 0; i < vectors.Length; ++i) vectorValues[i] = Shader.GetGlobalVector(vectors[i]);
            for (int i = 0; i < colors.Length; ++i) colorValues[i] = Shader.GetGlobalColor(colors[i]);
        }
        public void Apply()
        {
            for (int i = 0; i < floats.Length; ++i) Shader.SetGlobalFloat(floats[i], floatValues[i]);
            for (int i = 0; i < vectors.Length; ++i) Shader.SetGlobalVector(vectors[i], vectorValues[i]);
            for (int i = 0; i < colors.Length; ++i) Shader.SetGlobalColor(colors[i], colorValues[i]);
            foreach (var keyword in Shader.enabledGlobalKeywords)
                if (!desired.Contains(keyword.name)) Shader.DisableKeyword(keyword.name);
            foreach (var keyword in keywords)
                if (!Shader.IsKeywordEnabled(keyword.name)) Shader.EnableKeyword(keyword.name);
        }

        // Only model lighting inputs from SceneRenderAgent.Update. Camera and
        // terminal-room globals/keywords belong to the game's current camera.
        public void ApplyModel(MaterialPropertyBlock block, Quaternion rotation)
        {
            block.SetFloat(modelIntensity, floatValues[0]);
            var direction = rotation * (Vector3)vectorValues[0];
            block.SetVector(modelVectors[0], new Vector4(direction.x, direction.y, direction.z, vectorValues[0].w));
            for (int i = 1; i < 4; ++i) block.SetVector(modelVectors[i], vectorValues[i]);
        }
    }
}
